use lin::{Cell,persist::{self,LogRecord,Pack,SyncMode}};
use std::{collections::BTreeMap,fs::OpenOptions};
fn main(){
 let root=std::env::temp_dir().join(format!("lin-physical-tail-{}",std::process::id()));std::fs::create_dir(&root).unwrap();let path=root.join("source");let mut f=OpenOptions::new().create_new(true).read(true).write(true).open(&path).unwrap();let mut count=0;let mut buf=Vec::new();let mut first_end=0;
 for generation in [1,2]{let row=BTreeMap::from([("id".into(),Cell::Text(format!("r{generation}"))),("embedding".into(),Cell::Vec(vec![0.0;768].into()))]);persist::append_record(&mut f,&LogRecord{r#gen:generation,next_id:generation+1,pack:Pack::Update{collection:"docs".into(),rows:vec![row]}},&mut buf,SyncMode::Full,&mut count).unwrap();if generation==1{first_end=count as usize;}}
 drop(f);let bytes=std::fs::read(&path).unwrap();let cut=first_end+(bytes.len()-first_end)/2;let mut results=Vec::new();
 for (name,fixture)in [("ordinary_torn",bytes[..cut].to_vec()),("padded_torn",{let mut v=bytes[..cut].to_vec();v.resize(1024*1024,0);v}),("padded_complete",{let mut v=bytes.clone();v.resize(1024*1024,0);v})]{let path=root.join(name);std::fs::write(&path,&fixture).unwrap();let mut file=OpenOptions::new().read(true).write(true).open(&path).unwrap();let mut generations=Vec::new();let outcome=persist::replay_log(&mut file,0,0,|r|{generations.push(r.r#gen);Ok(())});results.push(serde_json::json!({"case":name,"file_bytes":fixture.len(),"generations":generations,"replay_end":outcome.as_ref().ok(),"error":outcome.as_ref().err().map(ToString::to_string)}));}
 assert_eq!(results[0]["generations"],serde_json::json!([1]));assert!(results[0]["error"].is_null());assert!(results[1]["error"].as_str().unwrap().contains("corrupt log record"));assert_eq!(results[2]["generations"],serde_json::json!([1,2]));assert!(results[2]["error"].is_null());println!("{}",serde_json::json!({"first_frame_bytes":first_end,"complete_bytes":bytes.len(),"torn_bytes":cut,"results":results,"naive_physical_tail_compatible":false}));std::fs::remove_dir_all(root).unwrap();
}
